<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){global $TEXT;$files=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isFile())$files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=["/\b(?:require|require_once|include|include_once)\s*\(?\s*['\"]([^'\"]+)['\"]/i","/\b(?:import|export)\s+(?:[^'\";]+?\s+from\s+)?['\"]([^'\"]+)['\"]/i","/\b(?:src|href)\s*=\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match($TEXT,$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'sizes'=>$files,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);
if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s')]);exit;}
if(isset($_GET['read'])){ $p=ltrim(str_replace('\\','/',$_GET['read']),'\/'); if(!$p||blocked($p)||!isset($D['sizes'][$p])||!preg_match($TEXT,$p)){http_response_code(403);echo json_encode(['error'=>'File not editable']);exit;} $s=@file_get_contents($ROOT.'/'.$p); header('Content-Type:application/json');echo json_encode(['path'=>$p,'content'=>$s===false?'':$s]);exit; }
if(isset($_POST['save'],$_POST['path'],$_POST['content'])){ $p=ltrim(str_replace('\\','/',$_POST['path']),'\/'); if(!$p||blocked($p)||$p==='site-wire-live.php'||!isset($D['sizes'][$p])||!preg_match($TEXT,$p)){http_response_code(403);echo json_encode(['ok'=>0,'error'=>'File cannot be edited']);exit;} $ok=@file_put_contents($ROOT.'/'.$p,$_POST['content'],LOCK_EX); header('Content-Type:application/json');echo json_encode(['ok'=>$ok!==false,'message'=>$ok!==false?'Saved':'Save failed']);exit; }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Relationship Manager IDE</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#071016;color:#dce8ed;font-family:system-ui,sans-serif}.head{height:58px;border-bottom:1px solid #203139;padding:11px 16px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:750;font-size:16px}.brand b{color:#55dfce}.stats{font:9px monospace;color:#70858d}.app{height:calc(100% - 58px);display:flex}.folders{width:245px;border-right:1px solid #203139;padding:12px;overflow:auto}.folders h4{margin:0 0 8px;color:#607780;font:8px monospace}.search{width:100%;padding:8px;background:#09151b;border:1px solid #263d45;border-radius:6px;color:#fff;outline:0;font:9px monospace;margin-bottom:7px}.folder{padding:8px;border-radius:6px;color:#9aaeb5;font:9px monospace;cursor:pointer;display:flex;justify-content:space-between}.folder:hover,.folder.active{background:#102128;color:#64ded2}.count{color:#526b74}.main{flex:1;min-width:0;display:flex;flex-direction:column}.bar{height:43px;border-bottom:1px solid #203139;padding:8px 12px;display:flex;align-items:center;gap:5px}.crumb{font:8px monospace;color:#70858d;margin-right:auto}.button,.filter{border:1px solid #263d45;background:#09151b;color:#849aa2;border-radius:5px;padding:6px 9px;font:8px monospace;cursor:pointer}.button:hover,.filter:hover,.filter.active{color:#64ded2;border-color:#55dfce66}.files{height:145px;border-bottom:1px solid #203139;padding:9px;overflow:auto;display:flex;flex-wrap:wrap;align-content:flex-start;gap:5px}.file{border:1px solid #263d45;background:#0a151b;border-radius:5px;padding:7px 9px;color:#91a5ac;font:8px monospace;cursor:pointer;white-space:nowrap}.file:hover,.file.active{border-color:#55dfce;color:#e9ffff}.editor{flex:1;min-height:0;display:flex;flex-direction:column}.editorhead{height:34px;border-bottom:1px solid #203139;padding:8px 12px;font:8px monospace;color:#647d86}.code{flex:1;resize:none;border:0;outline:0;background:#060c11;color:#d7e4e8;padding:15px;font:12px/1.6 'Cascadia Code','Consolas',monospace;tab-size:2}.right{width:280px;border-left:1px solid #203139;padding:14px;overflow:auto}.right h3{margin:5px 0;font-size:13px}.tag{color:#59757f;font:7px monospace;letter-spacing:1px}.path{color:#55dfce;font:8px monospace;word-break:break-all}.summary{display:flex;gap:4px;margin-top:10px}.stat{flex:1;background:#0d1c22;border-radius:5px;padding:7px}.stat b{display:block;font:12px monospace}.stat span{font:7px monospace;color:#58717a}.list{margin-top:9px;font:8px monospace;color:#8da1a8;line-height:1.8}.status{position:fixed;right:16px;bottom:10px;color:#607982;font:8px monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#5be5bb;margin-right:6px}.notice{position:fixed;right:16px;bottom:30px;background:#102128;border:1px solid #29434b;padding:7px 10px;border-radius:5px;font:8px monospace;display:none}.notice.show{display:block}@media(max-width:850px){.right{display:none}.folders{width:190px}.files{height:120px}}
</style></head><body><header class="head"><div class="brand"><b>◇</b> SmartToolz Relationship Manager <span style="color:#607780;font-size:10px">/ IDE</span></div><div class="stats"><?php echo count($D['files']);?> files · <?php echo count($D['refs']);?> relations · <span style="color:#55dfce">LIVE</span></div></header><div class="app"><aside class="folders"><h4>EXPLORER</h4><input id="search" class="search" placeholder="Search…"><div id="folderList"></div></aside><main class="main"><div class="bar"><span id="crumb" class="crumb">Select a folder</span><button class="filter active" data-type="all">ALL</button><button class="filter" data-type="php">PHP</button><button class="filter" data-type="js">JS</button><button class="filter" data-type="css">CSS</button><button id="save" class="button">SAVE</button><button id="refresh" class="button">RESCAN</button></div><div id="files" class="files"><span style="font:8px monospace;color:#526a73">Select a folder.</span></div><section class="editor"><div class="editorhead" id="editorHead">NO FILE OPEN</div><textarea id="code" class="code" spellcheck="false" placeholder="Select a text file to edit…"></textarea></section></main><aside class="right"><div class="tag">RELATIONSHIPS</div><h3 id="rn">No file selected</h3><div id="rp" class="path"></div><div class="summary"><div class="stat"><b id="inc">0</b><span>IN</span></div><div class="stat"><b id="out">0</b><span>OUT</span></div><div class="stat"><b id="total">0</b><span>TOTAL</span></div></div><div id="rl" class="list"></div></aside></div><div id="notice" class="notice"></div><div class="status"><span class="led"></span><b id="status">LIVE</b></div><script>
var DATA=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?>,current='',selected='',filter='all',original='';
function el(id){return document.getElementById(id)}function folders(){var a={};DATA.files.forEach(function(f){var p=f.split('/');a[p[0]]=1});return Object.keys(a).sort()}function direct(folder){return DATA.files.filter(function(f){var r=f.substring(folder.length+1);return f.indexOf(folder+'/')===0&&r.indexOf('/')===-1})}function ok(f){if(filter==='all')return true;var e=(f.split('.').pop()||'').toLowerCase();if(filter==='php')return e==='php';if(filter==='js')return ['js','mjs','jsx','ts','tsx'].indexOf(e)>=0;if(filter==='css')return ['css','scss'].indexOf(e)>=0;return true}
function renderFolders(q){var b=el('folderList');b.innerHTML='';q=(q||'').toLowerCase();folders().forEach(function(f){if(q&&f.toLowerCase().indexOf(q)<0&&!DATA.files.some(function(x){return x.indexOf(f+'/')===0&&x.toLowerCase().indexOf(q)>=0}))return;var d=document.createElement('div');d.className='folder '+(f===current?'active':'');d.innerHTML='<span>▾ '+f+'</span><span class="count">'+direct(f).length+'</span>';d.onclick=function(){openFolder(f)};b.appendChild(d)})}
function openFolder(f){current=f;el('crumb').textContent=f+' /';var b=el('files');b.innerHTML='';var a=direct(f).filter(ok);el('files').dataset.folder=f;if(!a.length){b.innerHTML='<span style="font:8px monospace;color:#526a73">No matching files.</span>'}a.forEach(function(p){var d=document.createElement('button');d.className='file';d.textContent='▸ '+p.split('/').pop();d.onclick=function(){openFile(p,d)};b.appendChild(d)});renderFolders(el('search').value)}
function openFile(p,node){selected=p;document.querySelectorAll('.file').forEach(function(x){x.classList.remove('active')});if(node)node.classList.add('active');el('editorHead').textContent=p;fetch(location.pathname+'?read='+encodeURIComponent(p)).then(function(r){return r.json()}).then(function(d){if(d.error)throw Error(d.error);original=d.content;el('code').value=d.content;relation(p)}).catch(function(e){notice(e.message)})}
function relation(p){var inc=DATA.refs.filter(function(r){return r.to===p}),out=DATA.refs.filter(function(r){return r.from===p});el('rn').textContent=p.split('/').pop();el('rp').textContent=p;el('inc').textContent=inc.length;el('out').textContent=out.length;el('total').textContent=inc.length+out.length;var a=[];inc.forEach(function(r){a.push('← '+r.from)});out.forEach(function(r){a.push('→ '+r.to)});el('rl').innerHTML=a.length?a.join('<br>'):'No direct relationships'}
function notice(s){var n=el('notice');n.textContent=s;n.classList.add('show');setTimeout(function(){n.classList.remove('show')},2200)}
el('save').onclick=function(){if(!selected){notice('Open a file first');return}fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'save=1&path='+encodeURIComponent(selected)+'&content='+encodeURIComponent(el('code').value)}).then(function(r){return r.json()}).then(function(d){if(!d.ok)throw Error(d.error||'Save failed');original=el('code').value;notice('Saved: '+selected)}).catch(function(e){notice(e.message)})};el('refresh').onclick=function(){location.reload()};el('search').oninput=function(){renderFolders(this.value);if(current)openFolder(current)};document.querySelectorAll('.filter').forEach(function(b){b.onclick=function(){document.querySelectorAll('.filter').forEach(function(x){x.classList.remove('active')});b.classList.add('active');filter=b.dataset.type;if(current)openFolder(current)}});el('code').addEventListener('keydown',function(e){if(e.key==='Tab'){e.preventDefault();var a=this.selectionStart,b=this.selectionEnd;this.value=this.value.substring(0,a)+'  '+this.value.substring(b);this.selectionStart=this.selectionEnd=a+2}});
setInterval(function(){fetch(location.pathname+'?pulse=1&_='+Date.now(),{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){el('status').textContent='LIVE · '+d.time}).catch(function(){el('status').textContent='OFFLINE'})},3000);renderFolders('');
</script></body></html>